import * as THREE from 'three';
import {OrbitControls} from './vendor/three/OrbitControls.js';
import {SVGRenderer} from './vendor/three/renderers/SVGRenderer.js';
// Every coordinate comes from a floor's own photograph. These units are not metres.
export async function createFloorModel(host,G,events){
 const W=G.width,H=G.height,S=.1,span=Math.max(W,H)*S;
 const world=(p,y=0)=>new THREE.Vector3((p[0]-W/2)*S,y,(p[1]-H/2)*S);
 const centre=r=>Number.isFinite(r.x)?[r.x,r.y]:r.points.reduce((a,p)=>[a[0]+p[0]/r.points.length,a[1]+p[1]/r.points.length],[0,0]);
 function shape(points,holes=[]){const s=new THREE.Shape(points.map(p=>new THREE.Vector2((p[0]-W/2)*S,-(p[1]-H/2)*S)));for(const h of holes)if(h.length>=3)s.holes.push(new THREE.Path(h.map(p=>new THREE.Vector2((p[0]-W/2)*S,-(p[1]-H/2)*S))));return s;}
 const probe=document.createElement('canvas');let renderer,software=false;
 if(probe.getContext('webgl2'))renderer=new THREE.WebGLRenderer({canvas:probe,antialias:true,alpha:true});else{renderer=new SVGRenderer();software=true;renderer.setQuality('high');host.classList.add('software-model')}
 renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0xf2f5fb,0);renderer.outputColorSpace=THREE.SRGBColorSpace;
 const ns='http://www.w3.org/2000/svg';let photoGroup;
 if(software){const under=document.createElementNS(ns,'svg');under.classList.add('model-photo-underlay');under.setAttribute('aria-hidden','true');host.appendChild(under);photoGroup=document.createElementNS(ns,'g');under.appendChild(photoGroup);const clip=document.createElementNS(ns,'clipPath');clip.id='floor-photo-mask';const path=document.createElementNS(ns,'path');path.setAttribute('d',G.outlines.flatMap(o=>[o.points,...(o.holes||[])]).map(p=>'M'+p.map(v=>v.join(',')).join('L')+'Z').join(''));path.setAttribute('clip-rule','evenodd');clip.appendChild(path);photoGroup.appendChild(clip);const img=document.createElementNS(ns,'image');img.setAttribute('href',G.image);img.setAttribute('width',W);img.setAttribute('height',H);img.setAttribute('opacity','.72');img.setAttribute('clip-path','url(#floor-photo-mask)');photoGroup.appendChild(img)}
 host.appendChild(renderer.domElement);renderer.domElement.classList.add('model-render-surface');renderer.domElement.setAttribute('role','img');renderer.domElement.setAttribute('aria-label',`${G.building} 栋 ${G.floor} 三维剖切模型，拖动旋转、滚轮缩放。`);
 const scene=new THREE.Scene();scene.add(new THREE.HemisphereLight(0xffffff,0x99a9c7,software?0:2.1));if(software)scene.add(new THREE.AmbientLight(0xaeb7c6));const sun=new THREE.DirectionalLight(0xffffff,software?.7:1.3);sun.position.set(-45,100,60);scene.add(sun);
 const camera=new THREE.OrthographicCamera(-65,65,54,-54,.1,1500);camera.position.set(-16,150,100);
 const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.12;controls.minPolarAngle=.02;controls.maxPolarAngle=Math.PI*.43;controls.minZoom=.5;controls.maxZoom=12;controls.screenSpacePanning=true;
 const group=new THREE.Group();scene.add(group);const markerGroup=new THREE.Group();scene.add(markerGroup);const labelLayer=document.createElement('div');labelLayer.className='model-labels';host.appendChild(labelLayer);
 const hits=[],floorHits=[],roomObjects=new Map(),labelObjects=[];let active=false,picking=false,raf=0,animation=null,selected=null,width=1,height=1,markerLabels=[];
 const material=(color,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.85,...extra});
 function surface(points,color,elevation=.02,holes=[],opacity=1){const geo=new THREE.ShapeGeometry(shape(points,holes));geo.rotateX(-Math.PI/2);const mesh=new THREE.Mesh(geo,material(color,{side:THREE.DoubleSide,transparent:opacity<1,opacity,depthWrite:opacity===1}));mesh.position.y=elevation;group.add(mesh);return mesh;}
 let texture;if(!software){texture=await new THREE.TextureLoader().loadAsync(G.image);texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=renderer.capabilities.getMaxAnisotropy();}
 for(const outline of G.outlines){const floor=surface(outline.points,0xffffff,0,outline.holes||[],software?0:1);floor.userData.kind='floor';floorHits.push(floor);floor.renderOrder=-20;
  if(texture){const p=floor.geometry.attributes.position,uv=floor.geometry.attributes.uv;for(let i=0;i<p.count;i++)uv.setXY(i,(p.getX(i)/S+W/2)/W,1-(p.getZ(i)/S+H/2)/H);floor.material.map=texture;floor.material.needsUpdate=true;}
  for(const points of [outline.points,...(outline.holes||[])]){const line=new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(points.map(p=>world(p,.025))),new THREE.LineBasicMaterial({color:0x8a9cb7,transparent:true,opacity:.5}));group.add(line)}
 }
 const wallMaterial=material(0xe4edf9,{transparent:true,opacity:.94}),edgeMaterial=new THREE.LineBasicMaterial({color:0x8da4c6,transparent:true,opacity:.4});
 function wall(a,b){const va=world(a),vb=world(b),length=va.distanceTo(vb);if(length<.03)return;const m=new THREE.Mesh(new THREE.BoxGeometry(length,1.5,.16),wallMaterial);m.position.copy(va.clone().add(vb).multiplyScalar(.5));m.position.y=.75;m.rotation.y=-Math.atan2(vb.z-va.z,vb.x-va.x);group.add(m);const edges=new THREE.LineSegments(new THREE.EdgesGeometry(m.geometry),edgeMaterial);m.add(edges)}
 function walls(r){r.points.forEach((a,i)=>{const b=r.points[(i+1)%r.points.length],len=Math.hypot(b[0]-a[0],b[1]-a[1]);const openings=(r.doors||[]).filter(d=>d.edge===i).map(d=>[Math.max(0,d.t-d.width/len/2),Math.min(1,d.t+d.width/len/2)]).sort((a,b)=>a[0]-b[0]);const at=t=>[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];let from=0;for(const [lo,hi]of openings){if(lo>from)wall(at(from),at(lo));from=Math.max(from,hi)}if(from<1)wall(at(from),b)})}
 function label(text,p,kind,action,id){const el=document.createElement(action?'button':'span');el.className='model-label '+kind;el.textContent=text;if(action){el.type='button';el.onclick=e=>{e.stopPropagation();action()};el.setAttribute('aria-label','查看 '+id)}labelLayer.appendChild(el);const item={el,p:world(p,2),kind,id};labelObjects.push(item);return item;}
 for(const r of G.rooms){let fill;if(r.points?.length>=3){fill=surface(r.points,0xb2c9ef,.04,[],0);fill.userData={kind:'room',room:r};hits.push(fill);walls(r)}const c=centre(r),l=label(r.id,c,'room'+(r.points?'':' point-only')+(r.status==='needs-review'?' needs-review':''),()=>events.select(r.id),r.id);roomObjects.set(r.id,{fill,label:l,data:r})}
 for(const pair of G.walls||[])wall(pair[0],pair[1]);
 function updateLabels(){const taken=[];const ordered=[...labelObjects].sort((a,b)=>(b.id===selected||b.kind==='marker')-(a.id===selected||a.kind==='marker'));for(const l of ordered){const v=l.p.clone().project(camera),x=(v.x+1)*width/2,y=(1-v.y)*height/2,important=l.id===selected||l.kind==='marker';let visible=v.z>-1&&v.z<1&&x>12&&x<width-12&&y>12&&y<height-12;const half=l.kind==='marker'?21:33,box=[x-half,y-9,x+half,y+9];if(visible&&!important&&taken.some(b=>box[0]<b[2]&&box[2]>b[0]&&box[1]<b[3]&&box[3]>b[1]))visible=false;if(visible)taken.push(box);l.el.hidden=!visible;l.el.style.transform=`translate(${x}px,${y}px) translate(-50%,-50%)`}}
 function updatePhoto(){if(!photoGroup)return;const project=p=>{const v=world(p).project(camera);return [(v.x+1)*width/2,(1-v.y)*height/2]};const a=project([0,0]),b=project([W,0]),c=project([0,H]);photoGroup.setAttribute('transform',`matrix(${(b[0]-a[0])/W} ${(b[1]-a[1])/W} ${(c[0]-a[0])/H} ${(c[1]-a[1])/H} ${a[0]} ${a[1]})`)}
 function tick(time){raf=0;if(!active)return;let moving=false;if(animation){const t=Math.min(1,(time-animation.start)/(matchMedia('(prefers-reduced-motion:reduce)').matches?1:450)),e=1-(1-t)**3;camera.position.lerpVectors(animation.a,animation.b,e);controls.target.lerpVectors(animation.ta,animation.tb,e);camera.zoom=animation.za+(animation.zb-animation.za)*e;camera.updateProjectionMatrix();moving=t<1;if(!moving)animation=null}const changed=controls.update();renderer.render(scene,camera);if(software)renderer.domElement.style.backgroundColor='transparent';updatePhoto();updateLabels();if(moving||changed)kick()}
 function kick(){if(active&&!raf)raf=requestAnimationFrame(tick)}
 controls.addEventListener('change',kick);controls.addEventListener('start',()=>{animation=null});
 function moveTo(target,zoom,direction){const offset=direction||camera.position.clone().sub(controls.target);animation={start:performance.now(),a:camera.position.clone(),b:target.clone().add(offset),ta:controls.target.clone(),tb:target.clone(),za:camera.zoom,zb:zoom};kick()}
 function fit(){moveTo(new THREE.Vector3(0,0,0),1,new THREE.Vector3(-span*.1,span*1.4,span*.9))}
 function resize(){width=host.clientWidth;height=host.clientHeight;if(!width||!height)return;renderer.setSize(width,height);const aspect=width/height,v=Math.max(span*.54,W*S*.57/aspect);camera.left=-v*aspect;camera.right=v*aspect;camera.top=v;camera.bottom=-v;camera.updateProjectionMatrix();kick()}
 new ResizeObserver(resize).observe(host);let down;const raycaster=new THREE.Raycaster();
 renderer.domElement.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>6)return;down=null;const rect=renderer.domElement.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/width*2-1,-(e.clientY-rect.top)/height*2+1),camera);const found=raycaster.intersectObjects(picking?floorHits:hits,false);if(!found.length)return;const hit=found[0];if(picking)events.position({x:Math.round(hit.point.x/S+W/2),y:Math.round(hit.point.z/S+H/2)});else events.select(hit.object.userData.room.id)});
 return {
 setActive(on){active=on;host.hidden=!on;resize();fit();kick()},
 setSelected(id){selected=id;for(const [k,r]of roomObjects){if(r.fill){r.fill.material.opacity=k===id?.45:0;r.fill.material.color.setHex(0x6b98eb)}r.label.el.classList.toggle('selected',k===id)}kick()},
 focus(id){const r=roomObjects.get(id);if(r)moveTo(world(centre(r.data)),2.8)},fit,
 zoom(factor){animation=null;camera.zoom=Math.max(.5,Math.min(12,camera.zoom/factor));camera.updateProjectionMatrix();kick()},
 setTopView(){moveTo(controls.target.clone(),camera.zoom,new THREE.Vector3(0,span*1.6,.01))},setPicking(on){picking=on;host.classList.toggle('pick-mode',on)},
 setMarkers(origin,destination){for(const m of [...markerGroup.children]){markerGroup.remove(m);m.geometry.dispose();m.material.dispose()}for(const l of markerLabels){l.el.remove();labelObjects.splice(labelObjects.indexOf(l),1)}markerLabels=[];for(const [r,color,text]of [[origin,0x258779,'起点'],[destination,0x3265d8,'终点']])if(r?.building===G.building&&r?.floor===G.floor){const m=new THREE.Mesh(new THREE.CylinderGeometry(.6,.6,3,12),material(color));m.position.copy(world([r.x,r.y],1.7));markerGroup.add(m);const l=label(text,[r.x,r.y],'marker',null);l.p.y=4.8;if(text==='终点')l.el.classList.add('target');markerLabels.push(l)}kick()}
 };
}
